def fail(msg):
    print("::error::" + msg)
    sys.exit(1)

def write_new_files():
    for dest, b64 in NEW_FILES.items():
        path = os.path.join(ROOT, dest)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as f:
            f.write(base64.b64decode("".join(b64.split())))
        print("created " + dest)

def squash(text):
    """포맷 차이를 무시한 비교용 문자열을 만듭니다. 실제 파일을 고칠 때는 쓰지 않습니다.

    ktlint 는 긴 줄을 끊으면서 점이나 괄호 앞에 없던 줄바꿈을 넣습니다.
    그래서 공백을 한 칸으로 누르는 것만으로는 부족하고,
    기호에 붙은 공백까지 없애야 같은 코드로 인식됩니다.
    낱말 사이의 공백 한 칸은 남겨서 서로 다른 토큰이 붙어버리는 일은 막습니다."""
    collapsed = re.sub(r"\s+", " ", text)
    return re.sub(r"\s*([^\w\s])\s*", r"\1", collapsed).strip()


def patch(path, old, new, label, sentinel=None):
    """sentinel: 패치 후에만 존재하는 문자열. 새 내용이 기존 앵커를 통째로
    포함하는 경우 old가 여전히 남아 있으므로 별도 표식이 필요합니다."""
    full = os.path.join(ROOT, path)
    if not os.path.exists(full):
        fail("file not found: " + path)
    text = open(full, encoding="utf-8").read()
    marker = sentinel if sentinel is not None else new
    # ktlintFormat 을 돌리면 이미 삽입된 코드의 줄바꿈과 들여쓰기가 바뀝니다.
    # 그러면 표식을 글자 그대로는 못 찾으므로, 공백을 무시하고 한 번 더 확인합니다.
    if marker in text or squash(marker) in squash(text):
        print("already applied: " + label)
        return
    count = text.count(old)
    if count == 0:
        fail("anchor not found in " + path + " (" + label + "). "
             "AnkiDroid upstream may have changed this code.")
    if count > 1:
        fail("anchor matched " + str(count) + " times in " + path + " (" + label + ")")
    open(full, "w", encoding="utf-8").write(text.replace(old, new))
    print("patched " + label)

def append_once(path, text, sentinel, label):
    full = os.path.join(ROOT, path)
    if not os.path.exists(full):
        fail("file not found: " + path)
    body = open(full, encoding="utf-8").read()
    if sentinel in body or squash(sentinel) in squash(body):
        print("already applied: " + label)
        return
    if not body.endswith("\n"):
        body += "\n"
    open(full, "w", encoding="utf-8").write(body + text)
    print("appended " + label)


# ---------------------------------------------------------------- 1. split screen
def rename_layout_folder():
    src = os.path.join(ROOT, "AnkiDroid/src/main/res/layout-sw600dp")
    dst = os.path.join(ROOT, "AnkiDroid/src/main/res/layout-sw720dp")
    if os.path.isdir(dst):
        print("already applied: layout folder")
        return
    if not os.path.isdir(src):
        fail("layout-sw600dp not found")
    os.rename(src, dst)
    print("renamed layout-sw600dp -> layout-sw720dp")

